input.command:
python3 - <<'E'
p='bookly/app.js'
s=open(p).read()
s=s.replace('''  // TODO S02: one button per slot
''','''  list.forEach((t) => {
    const b = document.createElement("button");
    b.className = "slot";
    b.textContent = t;
    el.appendChild(b);
  });
  if (list.length) el.classList.add("slot-grid"); else el.classList.remove("slot-grid");
''')
open(p,'w').write(s)
p='bookly/index.html'
s=open(p).read()
s=s.replace('''    <!-- S02: the slot grid goes here. See .skillator/clone/recon.md FL01 -->
''','''    <!-- S02: slot buttons are rendered here by app.js -->
''')
open(p,'w').write(s)
open('bookly/styles.css','a').write('''.slot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.slot { padding: 10px 14px; border: 0; border-radius: 999px; background: var(--accent); color: var(--on-accent); font: inherit; cursor: pointer; }
.slot:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
.slot:disabled { opacity: .5; cursor: not-allowed; }
''')
p='TICKETS.md'
s=open(p).read()
s=s.replace('## Agent-found','- [x] S02 — slot grid: 4-col pill buttons per day, built from our own tokens\n\n## Agent-found')
open(p,'w').write(s)
